mapper.select:
SELECT history_seq as "historySeq", dm_id as "dmId", obj_owner as "objOwner", obj_nm as "objNm", attr_nm as "attrNm", input_kr_nm as "inputKrNm", resolved_kr_nm as "resolvedKrNm", resolved_en_nm as "resolvedEnNm", resolved_terms_id as "resolvedTermsId", resolved_data_type as "resolvedDataType", resolved_data_len as "resolvedDataLen", resolve_reason as "resolveReason", change_user_id as "changeUserId", change_dt as "changeDt" FROM TB_TERM_RESOLVE_HISTORY WHERE 1=1
AND change_user_id = #{currentUserId}
AND change_user_id = #{changeUserId}
AND dm_id = #{dmId}
AND input_kr_nm LIKE '%' || #{inputKrNm} || '%'
AND resolved_kr_nm LIKE '%' || #{resolvedKrNm} || '%'
AND resolved_en_nm ILIKE '%' || #{resolvedEnNm} || '%'
AND COALESCE(resolved_kr_nm,'') != COALESCE(input_kr_nm,'')
AND COALESCE(resolved_kr_nm,'') = COALESCE(input_kr_nm,'')
AND change_dt >= #{fromDt}
AND change_dt <= #{toDt}
ORDER BY history_seq DESC LIMIT 500
